/**
 * Claude session-management helpers — voice picks which conversation a
 * delegation lands in. See /docs/agents/action-registry §5 + the
 * session-management design discussion.
 *
 * Server-side only. Backed by harness_shared.claude_sessions PG table.
 *
 * Three layers of memory (kept small, regenerated lazily):
 *   1. Title — 5-10 words generated by haiku-4-5 after the first turn
 *   2. Summary — 40-60 words regenerated every 5 turns or on 5min idle
 *   3. The actual claude --resume conversation (Claude truncates as needed)
 */

import { withWorkspace } from '@restart/db-org';

export interface ClaudeSessionRow {
  id: number;
  workspace: string;
  claudeSessionId: string;
  title: string | null;
  summary: string | null;
  status: 'open' | 'archived';
  createdAt: string;
  lastActiveAt: string;
  turnCount: number;
  origin: 'voice' | 'panel' | 'oracle';
  initiatorMsg: string | null;
}

export interface ListSessionsArgs {
  workspace: string;
  status?: 'open' | 'archived' | 'all';
  limit?: number;
}

export async function listClaudeSessions(args: ListSessionsArgs): Promise<ClaudeSessionRow[]> {
  const status = args.status ?? 'open';
  const limit = Math.min(50, Math.max(1, args.limit ?? 20));
  return withWorkspace(args.workspace, async (tx) => {
    const rows = status === 'all'
      ? await tx`
          SELECT id, workspace, claude_session_id, title, summary, status,
                 created_at, last_active_at, turn_count, origin, initiator_msg
          FROM harness_shared.claude_sessions
          WHERE workspace = ${args.workspace}
          ORDER BY last_active_at DESC
          LIMIT ${limit}
        `
      : await tx`
          SELECT id, workspace, claude_session_id, title, summary, status,
                 created_at, last_active_at, turn_count, origin, initiator_msg
          FROM harness_shared.claude_sessions
          WHERE workspace = ${args.workspace} AND status = ${status}
          ORDER BY last_active_at DESC
          LIMIT ${limit}
        `;
    return rows.map((r) => normalize(r));
  });
}

export async function getClaudeSession(workspace: string, sessionRef: string): Promise<ClaudeSessionRow | null> {
  return withWorkspace(workspace, async (tx) => {
    const rows = await tx`
      SELECT id, workspace, claude_session_id, title, summary, status,
             created_at, last_active_at, turn_count, origin, initiator_msg
      FROM harness_shared.claude_sessions
      WHERE workspace = ${workspace}
        AND (claude_session_id = ${sessionRef} OR id::text = ${sessionRef})
      LIMIT 1
    `;
    return rows.length > 0 ? normalize(rows[0]) : null;
  });
}

export async function createClaudeSession(args: {
  workspace: string;
  claudeSessionId: string;
  origin: 'voice' | 'panel' | 'oracle';
  initiatorMsg: string;
}): Promise<ClaudeSessionRow> {
  return withWorkspace(args.workspace, async (tx) => {
    const rows = await tx`
      INSERT INTO harness_shared.claude_sessions (
        workspace, claude_session_id, origin, initiator_msg, turn_count
      ) VALUES (
        ${args.workspace}, ${args.claudeSessionId}, ${args.origin}, ${args.initiatorMsg}, 1
      )
      RETURNING id, workspace, claude_session_id, title, summary, status,
                created_at, last_active_at, turn_count, origin, initiator_msg
    `;
    return normalize(rows[0]);
  });
}

export async function bumpClaudeSession(workspace: string, claudeSessionId: string): Promise<void> {
  await withWorkspace(workspace, async (tx) => {
    await tx`
      UPDATE harness_shared.claude_sessions
      SET turn_count = turn_count + 1,
          last_active_at = now()
      WHERE workspace = ${workspace} AND claude_session_id = ${claudeSessionId}
    `;
  });
}

export async function setClaudeSessionTitle(workspace: string, claudeSessionId: string, title: string): Promise<void> {
  await withWorkspace(workspace, async (tx) => {
    await tx`
      UPDATE harness_shared.claude_sessions
      SET title = ${title}
      WHERE workspace = ${workspace} AND claude_session_id = ${claudeSessionId}
    `;
  });
}

export async function setClaudeSessionSummary(workspace: string, claudeSessionId: string, summary: string): Promise<void> {
  await withWorkspace(workspace, async (tx) => {
    await tx`
      UPDATE harness_shared.claude_sessions
      SET summary = ${summary}
      WHERE workspace = ${workspace} AND claude_session_id = ${claudeSessionId}
    `;
  });
}

export async function archiveClaudeSession(workspace: string, sessionRef: string): Promise<void> {
  await withWorkspace(workspace, async (tx) => {
    await tx`
      UPDATE harness_shared.claude_sessions
      SET status = 'archived'
      WHERE workspace = ${workspace}
        AND (claude_session_id = ${sessionRef} OR id::text = ${sessionRef})
    `;
  });
}

/**
 * Auto-archive sessions idle for >24h. Called from the operator-chat
 * endpoint as a piggyback maintenance task; cheap, runs once per
 * delegation.
 */
export async function autoArchiveIdleSessions(workspace: string): Promise<number> {
  return withWorkspace(workspace, async (tx) => {
    const rows = await tx`
      UPDATE harness_shared.claude_sessions
      SET status = 'archived'
      WHERE workspace = ${workspace}
        AND status = 'open'
        AND last_active_at < now() - interval '24 hours'
      RETURNING id
    `;
    return rows.length;
  });
}

function normalize(r: any): ClaudeSessionRow {
  return {
    id: Number(r.id),
    workspace: r.workspace,
    claudeSessionId: r.claude_session_id,
    title: r.title,
    summary: r.summary,
    status: r.status,
    createdAt: r.created_at?.toISOString?.() ?? r.created_at,
    lastActiveAt: r.last_active_at?.toISOString?.() ?? r.last_active_at,
    turnCount: Number(r.turn_count),
    origin: r.origin,
    initiatorMsg: r.initiator_msg,
  };
}
